import sys
from collections import defaultdict

import logging
import csv
from taf.internal.managedobject import ManagedObject
from taf.converters.base import ConverterComponent

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class PmToCsvConverterObject(ManagedObject, ConverterComponent):
    """
    Convert PM XML files to one CSV file.
    """

    def __init__(self, pm_counter_log_reader, nidd_mapper, delimiter=None, output_file_name=None, **kwargs):
        """
        Create PM to CSV converter object.

        :param `taf.analyzer.pmcounter.PMCounterLogReader` pm_counter_log_reader: reader for PM files (XML)
        :param `taf.converters.pmtocsv.NiddMapper` nidd_mapper: mapper from PI_IDs to other PI information
        :param str delimiter: delimiter character e. g. "," or ";" default is ";"
        :param str output_file_name: name of output file. default = "Pm.csv"

        :return: PM to CSV converter object
        :rtype: PmToCsvConverterObject
        """
        super(PmToCsvConverterObject, self).__init__(**kwargs)
        self._pm_counter_log_reader = pm_counter_log_reader
        if delimiter is None:
            delimiter = ";"
        self._delimiter = delimiter
        if output_file_name is None:
            output_file_name = "Pm.csv"
        self._output_file_name = output_file_name
        self._nidd_mapper = nidd_mapper

    def convert(self):
        """
        Convert PM XML files to one CSV file.

        Create a file with
         * first column: PI_ID
         * second column: Managed Object Name
         * next columns: PM counter value, one column for each PM-file
         * if available, second to last column: Name of PI_ID (called: Short Description)
         * if available, last column: updating process name of PI_ID
        """

        pm_counter_values = defaultdict(lambda: defaultdict(list))
        timestamps = []

        for idx, pm_log_entry in enumerate(sorted(self._pm_counter_log_reader, key=lambda entry: entry.timestamp)):

            timestamps.append(str(pm_log_entry.timestamp))

            pi_id_list = pm_log_entry.pm_setup.keys()
            for pi_id, value in pm_log_entry.pm_setup.pi_dict(*pi_id_list).items():
                for managed_object_name, pm_counter_value in value.items():
                    pm_counter_values[pi_id][managed_object_name].extend(["-"] * (idx - len(pm_counter_values[pi_id][managed_object_name])))
                    pm_counter_values[pi_id][managed_object_name].append(pm_counter_value)

        for pi_id, x in pm_counter_values.items():
            for managed_object_name, performance_counter_values in x.items():
                pm_counter_values[pi_id][managed_object_name].extend(["-"] * (idx - len(performance_counter_values) + 1))

        self._write_csv_file(pm_counter_values, timestamps)

    def _open_output_file(self):
        if sys.version_info[0] >= 3:
            return open(self._output_file_name, 'w', newline="")
        else:
            return open(self._output_file_name, 'wb')

    def _write_csv_file(self, pm_counter_values, timestamps):
        with self._open_output_file() as file_obj:
            writer = csv.writer(
                file_obj,
                delimiter=self._delimiter,
                quotechar='"',
                quoting=csv.QUOTE_MINIMAL)

            self._write_header(timestamps, writer)
            self._write_body(pm_counter_values, writer)

    def _write_header(self, timestamps, writer):
        first_line = ["PI_ID", "Managed Object Name"]
        first_line.extend(timestamps)
        first_line.extend(["Short Description", "Updating Process Name"])
        writer.writerow(first_line)

    def _write_body(self, pm_counter_values, writer):
        for pi_id, x in sorted(pm_counter_values.items()):
            for managed_object_name, performance_counter_values in sorted(x.items()):
                line = [pi_id, managed_object_name]
                line.extend(performance_counter_values)
                line.append(self._get_nidd_info(pi_id, self._nidd_mapper.pi_id_to_name))
                line.append(self._get_nidd_info(pi_id, self._nidd_mapper.pi_id_to_updating_process_name))
                writer.writerow(line)

    def _get_nidd_info(self, pi_id, mapper_method):
        try:
            return mapper_method(pi_id).rstrip()
        except KeyError:
            return "-"
